    it = iter(data)
    n = next(it)
    m = next(it)
    f = [0] + [next(it) for _ in range(n)]

    g = [[] for _ in range(n + 1)]
    gr = [[] for _ in range(n + 1)]
    for _ in range(m):
        a = next(it)
        b = next(it)
        g[a].append(b)
        gr[b].append(a)

    # Step 1: find all nodes that can reach a use (f[i] == 2) via reverse graph
    from collections import deque
    can_reach_use = [False] * (n + 1)
    q = deque()
    for i in range(1, n + 1):
        if f[i] == 2:
            can_reach_use[i] = True
            q.append(i)
    while q:
        v = q.popleft()
        for u in gr[v]:
            if not can_reach_use[u]:
                can_reach_use[u] = True
                q.append(u)

    # Step 2: DFS with state 0/1/2
    # 0: no assignment seen yet
    # 1: exactly one assignment seen (and this node is that assignment)
    # 2: invalid (multiple assignments)
    state = [0] * (n + 1)
    vis = [0] * (n + 1)
    interesting = [0] * (n + 1)

    def dfs(v):
        vis[v] = 1
        cur_state = state[v]

        # If this node is a use and we are in state 1 (exactly one assign on path)
        if f[v] == 2 and cur_state == 1:
            # mark all nodes on this DFS stack that currently have state 1 as interesting
            # we don't maintain explicit stack, but any node with state 1 that can reach a use
            # is interesting; we'll mark this node and rely on propagation via recursion
            interesting[v] = 1

        for to in g[v]:
            if not can_reach_use[to]:
                continue
            ns = cur_state
            if f[to] == 1:
                if cur_state == 0:
                    ns = 1
                else:
                    ns = 2
            if ns == 2:
                continue
            if vis[to] == 0:
                state[to] = ns
                dfs(to)
            else:
                # already visited; if we reach a node that is in a path to a use and had state 1,
                # and this path also has state 1, mark it interesting
                if ns == 1 and state[to] == 1:
                    interesting[to] = 1

    # Start DFS from all nodes that can reach a use and are assignments or neutral
    for i in range(1, n + 1):
        if not can_reach_use[i]:
            continue
        if vis[i]:
            continue
        if f[i] == 1:
            state[i] = 1
        else:
            state[i] = 0
        dfs(i)

    # Propagate "interesting" backwards along paths that preserve single assignment
    # If a node is interesting and has state 1, its predecessors on valid paths are also interesting
    # We'll do reverse BFS restricted to nodes that can reach a use and don't introduce extra assigns.
    from collections import deque
    q = deque()
    for i in range(1, n + 1):
        if interesting[i]:
            q.append(i)
    while q:
        v = q.popleft()
        for u in gr[v]:
            if not can_reach_use[u]:
                continue
            # check if edge u->v can be part of a valid path with exactly one assign
            # If f[v]==1 and this is the unique assign, then u must have state 0 on that path.
            # If f[v]!=1, then u must have same state as v.
            # We approximate by ensuring we don't add a second assign.
            if f[v] == 1 and f[u] == 1:
                continue
            if interesting[u]:
                continue
            interesting[u] = 1
            q.append(u)

    out = []
    for i in range(1, n + 1):
        out.append('1' if interesting[i] else '0')
    sys.stdout.write('\n'.join(out))

