    gr = [[] for _ in range(n + 1)]
    for _ in range(m):
        a = next(it)
        b = next(it)
        g[a].append(b)
        gr[b].append(a)

    # Kosaraju to find SCCs
    visited = [False] * (n + 1)
    order = []

    def dfs1(v):
        stack = [(v, 0)]
        while stack:
            v, idx = stack.pop()
            if idx == 0:
                visited[v] = True
            if idx < len(g[v]):
                stack.append((v, idx + 1))
                to = g[v][idx]
                if not visited[to]:
                    stack.append((to, 0))
            else:
                order.append(v)

    for v in range(1, n + 1):
        if not visited[v]:
            dfs1(v)

    comp = [0] * (n + 1)
    comp_cnt = 0

    def dfs2(v, c):
        stack = [v]
        comp[v] = c
        while stack:
            v = stack.pop()
            for to in gr[v]:
                if comp[to] == 0:
                    comp[to] = c
                    stack.append(to)

    for v in reversed(order):
        if comp[v] == 0:
            comp_cnt += 1
            dfs2(v, comp_cnt)

    # Build condensation DAG
    dag = [[] for _ in range(comp_cnt + 1)]
    radj = [[] for _ in range(comp_cnt + 1)]
    for v in range(1, n + 1):
        cv = comp[v]
        for to in g[v]:
            cu = comp[to]
            if cv != cu:
                dag[cv].append(cu)
                radj[cu].append(cv)

    # Remove duplicate edges
    for i in range(1, comp_cnt + 1):
        if dag[i]:
            dag[i] = list(set(dag[i]))
        if radj[i]:
            radj[i] = list(set(radj[i]))

    # Mark SCCs that contain assign/use
    has_assign = [False] * (comp_cnt + 1)
    has_use = [False] * (comp_cnt + 1)
    for v in range(1, n + 1):
        c = comp[v]
        if f[v] == 1:
            has_assign[c] = True
        elif f[v] == 2:
            has_use[c] = True

    # DP from uses backwards: can_reach_use
    can_reach_use = [False] * (comp_cnt + 1)
    from collections import deque
    q = deque()
    for c in range(1, comp_cnt + 1):
        if has_use[c]:
            can_reach_use[c] = True
            q.append(c)

    while q:
        c = q.popleft()
        for p in radj[c]:
            if not can_reach_use[p]:
                can_reach_use[p] = True
                q.append(p)

    # DP from assigns forwards: can_reach_assign
    can_reach_assign = [False] * (comp_cnt + 1)
    q.clear()
    for c in range(1, comp_cnt + 1):
        if has_assign[c]:
            can_reach_assign[c] = True
            q.append(c)

    while q:
        c = q.popleft()
        for nxt in dag[c]:
            if not can_reach_assign[nxt]:
                can_reach_assign[nxt] = True
                q.append(nxt)

    # Determine interesting SCCs: reachable from assign and to use, and no assign on path except start
    # To ensure no other assign on path, we must ensure that along any path from assign SCC to use SCC,
    # no SCC with assign is passed except the starting one. This is equivalent to requiring that
    # for any SCC with assign, all reachable SCCs that can reach use must have has_assign == False.
    interesting_scc = [False] * (comp_cnt + 1)

    # For each assign SCC, BFS forward while avoiding other assign SCCs
    for start in range(1, comp_cnt + 1):
        if not has_assign[start]:
            continue
        # If this assign SCC itself cannot reach any use, skip
        if not can_reach_use[start]:
            continue
        # BFS
        q.clear()
        visited_scc = [False] * (comp_cnt + 1)
        q.append(start)
        visited_scc[start] = True
        while q:
            c = q.popleft()
            if has_use[c]:
                # All nodes visited in this BFS are interesting for this assign
                for x in range(1, comp_cnt + 1):
                    if visited_scc[x]:
                        interesting_scc[x] = True
            for nxt in dag[c]:
                if visited_scc[nxt]:
                    continue
                if has_assign[nxt] and nxt != start:
                    continue
                visited_scc[nxt] = True
                q.append(nxt)

    res = [0] * (n + 1)
    for v in range(1, n + 1):
        if interesting_scc[comp[v]]:
            res[v] = 1

    out = '\n'.join(str(res[i]) for i in range(1, n + 1))
    sys.stdout.write(out)

