    # dp[c] = True if from component c we can reach some component with use
    # and on the path (excluding starting component) there is no component with assign
    dp = [False] * (comp_cnt + 1)
    state = [0] * (comp_cnt + 1)  # 0=unvisited,1=visiting,2=done

    def dfs_dp(c):
        if state[c] == 2:
            return dp[c]
        state[c] = 1
        res = has_use[c]
        for to in cg[c]:
