    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    f = [0] * n
    for i in range(n):
        f[i] = int(next(it))

    g = [[] for _ in range(n)]
    gr = [[] for _ in range(n)]
    for _ in range(m):
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        g[a].append(b)
        gr[b].append(a)

    # Kosaraju to find SCCs
    visited = [False] * n
    order = []

    def dfs1(v):
        stack = [v]
        while stack:
            v = stack.pop()
            if v < 0:
                v = ~v
                order.append(v)
                continue
            if visited[v]:
                continue
            visited[v] = True
            stack.append(~v)
            for to in g[v]:
                if not visited[to]:
                    stack.append(to)

    for i in range(n):
        if not visited[i]:
            dfs1(i)

    comp = [-1] * n
    comp_cnt = 0

    def dfs2(v, cid):
        stack = [v]
        comp[v] = cid
        while stack:
            v = stack.pop()
            for to in gr[v]:
                if comp[to] == -1:
                    comp[to] = cid
                    stack.append(to)

    for v in reversed(order):
        if comp[v] == -1:
            dfs2(v, comp_cnt)
            comp_cnt += 1

    # Build condensation DAG
    cg = [[] for _ in range(comp_cnt)]
    has_assign = [False] * comp_cnt
    has_use = [False] * comp_cnt
    for i in range(n):
        cid = comp[i]
        if f[i] == 1:
            has_assign[cid] = True
        elif f[i] == 2:
            has_use[cid] = True
        for to in g[i]:
            cto = comp[to]
            if cto != cid:
                cg[cid].append(cto)

    # Remove duplicate edges
    for i in range(comp_cnt):
        if cg[i]:
            cg[i] = list(set(cg[i]))

    # DP over DAG: for each component, whether there exists a path starting
    # with an assignment in this component, ending with a use, and with no
    # other assignments on the path.
    # We propagate from components that have assignment.
    interesting_comp = [False] * comp_cnt

    # Topological order of condensation DAG
    indeg = [0] * comp_cnt
    for u in range(comp_cnt):
        for v in cg[u]:
            indeg[v] += 1

    from collections import deque
    q = deque()
    for i in range(comp_cnt):
        if indeg[i] == 0:
            q.append(i)

    topo = []
    while q:
        v = q.popleft()
        topo.append(v)
        for to in cg[v]:
            indeg[to] -= 1
            if indeg[to] == 0:
                q.append(to)

    # We will propagate from assign components forward.
    # For each component, we track if there is an "active" assignment path
    # reaching it without passing another assignment.
    active = [False] * comp_cnt

    # Initialize: components with assignment start active paths
    for cid in range(comp_cnt):
        if has_assign[cid]:
            active[cid] = True
            if has_use[cid]:
                interesting_comp[cid] = True

    # Process in topological order
    for u in topo:
        if not active[u]:
            continue
        for v in cg[u]:
            # If v has assignment, path cannot pass through it (would violate rule)
            if has_assign[v]:
                continue
            if not active[v]:
                active[v] = True
                if has_use[v]:
                    interesting_comp[v] = True

    # Now, for each component that is active and can reach a use, we need to
    # mark all nodes on some path from an assign to a use without another assign.
    # However, the above propagation already ensures that: any node in an active
    # component that is on such a path is interesting. Because within an SCC,
    # if the component is active and can reach a use (has_use or via edges),
    # all its nodes are reachable along such paths.
    # But we only marked components that themselves have use; we must also
    # propagate "interesting" backwards inside the DAG to mark components that
    # lie on paths between assign and use.
    # We'll do a reverse DP: from components where active and has_use, go
    # backwards along edges, stopping at assign components.

    # Build reverse condensation graph
    cgr = [[] for _ in range(comp_cnt)]
    for u in range(comp_cnt):
        for v in cg[u]:
            cgr[v].append(u)

    # Start from components that are active and have use
    queue = deque()
    on_path = [False] * comp_cnt
    for cid in range(comp_cnt):
        if active[cid] and has_use[cid]:
            on_path[cid] = True
            queue.append(cid)

    while queue:
        v = queue.popleft()
        for u in cgr[v]:
            # must be part of some active path
            if not active[u]:
                continue
            # cannot go past another assign (except starting assign components)
            if has_assign[u] and not on_path[u]:
                on_path[u] = True
                queue.append(u)
            elif not has_assign[u] and not on_path[u]:
                on_path[u] = True
                queue.append(u)

    res = [0] * n
    for i in range(n):
        if on_path[comp[i]]:
            res[i] = 1

    out = '\n'.join(str(x) for x in res)
    sys.stdout.write(out)

