                dfs1(to)
        order.append(v)

    for v in range(n):
        if not used[v]:
            dfs1(v)

    comp = [-1] * n
    comp_cnt = 0

    def dfs2(v, c):
        comp[v] = c
        for to in gr[v]:
            if comp[to] == -1:
                dfs2(to, c)

    for v in reversed(order):
        if comp[v] == -1:
            dfs2(v, comp_cnt)
            comp_cnt += 1

    # Build condensation DAG
    cg = [[] for _ in range(comp_cnt)]
    has_assign = [False] * comp_cnt
    has_use = [False] * comp_cnt

    for v in range(n):
        c = comp[v]
        if f[v] == 1:
            has_assign[c] = True
        if f[v] == 2:
            has_use[c] = True
        for to in g[v]:
            ct = comp[to]
            if ct != c:
                cg[c].append(ct)

    # Remove duplicate edges in condensation graph
    for i in range(comp_cnt):
        if cg[i]:
            cg[i] = list(set(cg[i]))

    # DP on condensation DAG: can we reach a use without passing another assign?
    # We propagate a state:
    # 0 = no interesting path from this SCC
    # 1 = there exists a path starting here with exactly one assign (in some SCC on path) and ending in a use, without another assign
    # We process in reverse topological order.

    # Topological order via DFS
    used_c = [False] * comp_cnt
    topo = []

    def dfs_c(v):
        used_c[v] = True
        for to in cg[v]:
            if not used_c[to]:
                dfs_c(to)
        topo.append(v)

    for v in range(comp_cnt):
        if not used_c[v]:
            dfs_c(v)

    dp = [0] * comp_cnt

    for v in topo:
        # combine children
        child_has = False
        child_assign = False
        child_use = False
        for to in cg[v]:
            if dp[to]:
                child_has = True
            if has_assign[to]:
                child_assign = True
            if has_use[to]:
                child_use = True

        # We need a path with exactly one assign and at least one use.
        # Cases:
        # - assign in this SCC, and from here we can reach a use without another assign
        #   i.e., there exists path to some SCC with use, and no SCC on path (excluding this) has assign.
        #   Approximated by: (has_assign[v] and (has_use[v] or (child_use and not child_assign)))
        # - assign in some descendant SCC, but no other assign on path before it:
        #   handled when processing that descendant; we just need to know if from v we can reach that SCC
        #   which is covered by child_has.
        if has_assign[v]:
            if has_use[v] or (child_use and not child_assign):
                dp[v] = 1
        if child_has:
            dp[v] = 1

    res = [0] * n
    for v in range(n):
        if dp[comp[v]]:
            res[v] = 1

    out = '\n'.join(str(x) for x in res)
    sys.stdout.write(out)

